fn main() {
    let literal: &str = "hello";
    let mut owned: String = String::from(literal);
    owned.push_str(", world");
    owned.push('!');
    println!("{owned}");
    let view: &str = &owned;   // borrow a String as &str
    println!("{} characters", view.len());
}

fn main() {
    let first = "Ada";
    let last = "Lovelace";
    let full = format!("{first} {last}");
    println!("{full}");

    let s = String::from("tic") + "-tac" + "-toe";
    println!("{s}");
}

fn main() {
    let line = "  Rust is fun  ";
    let clean = line.trim();
    println!("[{clean}]");
    println!("{}", clean.to_uppercase());
    println!("{}", clean.contains("fun"));
    println!("{}", clean.replace("fun", "great"));
    for word in clean.split_whitespace() {
        println!("word: {word}");
    }
}

